R=C=19
g=[[0]*C for _ in range(R)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
# horizontal spans first
for (r,c),v in centers.items():
    for j in range(C): g[r][j]=v
# vertical overwrite
for (r,c),v in centers.items():
    for i in range(R): g[i][c]=v
# restore original crosses and centers
for (r,c),v in centers.items():
    g[r][c]=v
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        g[r+dr][c+dc]=3
for row in g: print(row)

